import sys
from collections import deque

def min_mutation_brute(start, end, bank):
    bank_set = set(bank)
    if end not in bank_set:
        return -1
    q = deque([(start, 0)])
    seen = {start}
    chars = 'ACGT'
    while q:
        s, steps = q.popleft()
        if s == end:
            return steps
        for i in range(8):
            for ch in chars:
                if ch == s[i]:
                    continue
                nxt = s[:i] + ch + s[i + 1:]
                if nxt in bank_set and nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, steps + 1))
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    start = data[0]
    end = data[1]
    n = int(data[2])
    bank = data[3:3 + n]
    print(min_mutation_brute(start, end, bank))

import sys
from collections import deque

def min_mutation_opt(start, end, bank):
    bank_set = set(bank)
    if end not in bank_set:
        return -1
    wild = {}
    for g in bank_set:
        for i in range(8):
            pat = g[:i] + '*' + g[i + 1:]
            wild.setdefault(pat, []).append(g)
    q = deque([(start, 0)])
    seen = {start}
    while q:
        s, steps = q.popleft()
        if s == end:
            return steps
        for i in range(8):
            pat = s[:i] + '*' + s[i + 1:]
            for nxt in wild.get(pat, []):
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, steps + 1))
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    start = data[0]
    end = data[1]
    n = int(data[2])
    bank = data[3:3 + n]
    print(min_mutation_opt(start, end, bank))

import sys

def min_mutation_best(start, end, bank):
    bank_set = set(bank)
    if end not in bank_set:
        return -1
    if start == end:
        return 0
    chars = 'ACGT'
    front = {start}
    back = {end}
    steps = 0
    while front:
        steps += 1
        nxt = set()
        for s in front:
            for i in range(8):
                for ch in chars:
                    if ch == s[i]:
                        continue
                    m = s[:i] + ch + s[i + 1:]
                    if m in back:
                        return steps
                    if m in bank_set:
                        nxt.add(m)
        bank_set -= nxt
        front = nxt
        if len(front) > len(back):
            front, back = back, front
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    start = data[0]
    end = data[1]
    n = int(data[2])
    bank = data[3:3 + n]
    print(min_mutation_best(start, end, bank))
